#!/bin/sh
# Publish to, and re-index, the f3s FreeBSD package repository on its
# storage host (f0, /data/nfs/k3svolumes/pkgrepo/freebsd/...).
#
#   freebsd-repo.sh add PACKAGE REPOSITORY   place one .pkg in All/, re-index
#   freebsd-repo.sh index REPOSITORY         regenerate the catalog only
#
# The catalog (meta.conf, meta, data.pkg, packagesite.pkg) describes the
# whole repository, so it is always generated by `pkg repo` over the full
# REPOSITORY tree. It is never built from a work directory that holds only a
# just-built package: copying such a one-package catalog over the repo (as
# pkg-freebsd.sh used to, task h54) hides every other package from clients.
#
# Publication is crash-safe:
# - packages are copied to a hidden temp file in All/ and renamed into place;
# - the catalog is generated into a hidden staging directory inside
#   REPOSITORY (pkg repo does not traverse dot-directories, and staying on
#   the same filesystem makes every rename(2) atomic);
# - the staged catalog must list every All/*.pkg that existed before
#   indexing began, since `pkg repo` merely warns about (and drops) an
#   unreadable package and still exits 0;
# - only then are the files renamed over the live ones. Any failure leaves
#   the previous catalog in place.
# A lock directory serializes concurrent indexers. Every publisher indexes
# after its own package is in place, so the last indexer sees all packages.
#
# Runs as root (doas) in production. The repository is unsigned
# (signature_type "NONE" on the clients), so `pkg repo` gets no key; repo
# signing would add the signer argument in index_repository only.
set -eu

# Archives first, the metadata last: meta.conf/meta carry the format only and
# are identical across runs, so a client never pairs incompatible files.
CATALOG_FILES='data.pkg packagesite.pkg meta.conf meta'
# Seconds to wait for a concurrent indexer before giving up.
LOCK_WAIT=${FREEBSD_REPO_LOCK_WAIT:-120}

# State the EXIT trap cleans up; each is set only once it exists.
temp_package=''
stage=''
lock=''

fail() { printf 'freebsd-repo: %s\n' "$*" >&2; exit 1; }

cleanup() {
    test -z "$temp_package" || rm -f "$temp_package"
    test -z "$stage" || rm -rf "$stage"
    test -z "$lock" || rmdir "$lock"
}

check_repository() {
    test -d "$1" && test ! -L "$1" || fail "Repository must already exist: $1"
    test -d "$1/All" && test ! -L "$1/All" \
        || fail "Repository All directory must already exist: $1/All"
}

acquire_lock() {
    candidate=$1/.catalog.lock
    waited=0
    until mkdir "$candidate" 2>/dev/null; do
        test "$waited" -lt "$LOCK_WAIT" || fail "Catalog lock still held" \
            "after ${LOCK_WAIT}s: $candidate (remove it if no publisher runs)"
        sleep 1
        waited=$((waited + 1))
    done
    lock=$candidate
}

# Print the file names of All/*.pkg, one per line; fail when there is none
# so an empty or unmounted All/ never yields an empty live catalog.
list_packages() {
    for package in "$1"/All/*.pkg; do
        test -f "$package" || fail "No packages in $1/All; refusing to index"
        printf '%s\n' "${package##*/}"
    done
}

# verify_catalog STAGE PACKAGES: both catalog archives list every package.
verify_catalog() {
    for file in $CATALOG_FILES; do
        test -s "$1/$file" || fail "pkg repo did not write $file"
    done
    manifests=$(tar -xOf "$1/packagesite.pkg" packagesite.yaml)
    data=$(tar -xOf "$1/data.pkg" data)
    while IFS= read -r name; do
        entry="\"repopath\":\"All/$name\""
        case $manifests in *"$entry"*) ;; *) fail "packagesite lacks $name";; esac
        case $data in *"$entry"*) ;; *) fail "data lacks $name";; esac
    done <<EOF
$2
EOF
}

index_repository() {
    repo=$1
    check_repository "$repo"
    case $LOCK_WAIT in ''|*[!0-9]*) fail "Invalid lock wait: $LOCK_WAIT";; esac
    acquire_lock "$repo"
    # Snapshot under the lock: a package placed while pkg repo runs is
    # covered by its own publisher's index run, which waits for this lock.
    packages=$(list_packages "$repo")
    stage=$(mktemp -d "$repo/.catalog.XXXXXXXXXX")
    pkg repo -q -o "$stage" "$repo"
    verify_catalog "$stage" "$packages"
    for file in $CATALOG_FILES; do
        chmod 644 "$stage/$file"
        mv -f "$stage/$file" "$repo/$file"
    done
    count=$(printf '%s\n' "$packages" | wc -l | tr -d ' ')
    printf 'Indexed %s: %s packages\n' "$repo" "$count"
    printf '%s\n' "$packages" | sed 's/^/  /'
}

add_package() {
    artifact=$1
    repo=$2
    name=${artifact##*/}
    test -f "$artifact" && test ! -L "$artifact" || fail "Invalid package: $artifact"
    case $name in
        .*|*[!A-Za-z0-9._+-]*) fail "Unsafe package name: $name";;
        *.pkg) ;;
        *) fail "Not a .pkg file: $name";;
    esac
    check_repository "$repo"
    temp_package=$(mktemp "$repo/All/.publish.XXXXXXXXXX")
    cp "$artifact" "$temp_package"
    test "$(sha256 -q "$artifact")" = "$(sha256 -q "$temp_package")" \
        || fail 'Copied package checksum mismatch'
    chmod 644 "$temp_package"
    # rename(2): readers see the old file or the new one, never a partial
    # copy. A republished same-version package replaces the old file, as
    # pkg-freebsd.sh always did.
    mv -f "$temp_package" "$repo/All/$name"
    temp_package=''
    printf 'Placed %s\n' "$repo/All/$name"
    index_repository "$repo"
}

trap cleanup EXIT
trap 'exit 1' HUP INT TERM

case "${1:-}" in
    add) test "$#" -eq 3 || fail 'Usage: add PACKAGE REPOSITORY'
        add_package "$2" "$3";;
    index) test "$#" -eq 2 || fail 'Usage: index REPOSITORY'
        index_repository "$2";;
    *) fail 'Usage: freebsd-repo.sh add PACKAGE REPOSITORY | index REPOSITORY';;
esac
